count-pairs-whose-sum-is-less-than-targe:
class Solution:
    def countPairs(self, nums: List[int], target: int) -> int:
        ans = 0
        n = len(nums)
        for i in range(n):
            for j in range(i+1, n):
                if nums[i]+nums[j] < target:
                    ans += 1
        return ans

